import { SOGNodeType, SOGEdgeType } from '../../sog/sog-core-schema';
/**
 * ontology-versioning.ts — 本体版本管理 (Phase C4)
 *
 * 双时序查询 + diff + 回滚。所有三元组带 valid_from/valid_to。
 * 永不物理删除——这是硬边界。
 */
import type { GraphStore } from './graph-store';
import type { Triple, GraphNode } from './types';
import { createLogger } from '../../infra/logger';

const log = createLogger('diagnosis/ontology-versioning');

// ═══ Version Snapshot ═══

export interface OntologySnapshot {
  id: string;
  graph: string;
  timestamp: string;
  nodeCount: number;
  edgeCount: number;
  nodes: GraphNode[];
  triples: Triple[];
}

const snapshots = new Map<string, OntologySnapshot[]>();

export function createSnapshot(store: GraphStore, graph: string): OntologySnapshot {
  const id = `snap_${Date.now().toString(36)}`;
  const ts = new Date().toISOString();
  const persons = store.queryNodes(SOGNodeType.PERSON, undefined, graph);
  const teams = store.queryNodes(SOGNodeType.TEAM, undefined, graph);
  const agents = store.queryNodes(SOGNodeType.AGENT, undefined, graph);
  const tools = store.queryNodes(SOGNodeType.TOOL, undefined, graph);
  const clients = store.queryNodes(SOGNodeType.CLIENT, undefined, graph);
  const events = store.queryNodes(SOGNodeType.EVENT, undefined, graph);
  const docs = store.queryNodes(SOGNodeType.DOCUMENT, undefined, graph);
  const financials = store.queryNodes(SOGNodeType.FINANCIAL, undefined, graph);
  const nodes = [...persons, ...teams, ...agents, ...tools, ...clients, ...events, ...docs, ...financials];
  const triples = store.queryTriples({}, graph);

  const snap: OntologySnapshot = { id, graph, timestamp: ts, nodeCount: nodes.length, edgeCount: triples.length, nodes, triples };
  if (!snapshots.has(graph)) snapshots.set(graph, []);
  snapshots.get(graph)!.push(snap);

  // Keep last 10 snapshots
  const graphSnaps = snapshots.get(graph)!;
  while (graphSnaps.length > 10) graphSnaps.shift();

  log.info({ id, nodeCount: nodes.length, edgeCount: triples.length }, '[versioning] Snapshot created');
  return snap;
}

// ═══ Diff ═══

export interface OntologyDiff {
  addedNodes: GraphNode[];
  removedNodes: GraphNode[];
  addedEdges: Triple[];
  removedEdges: Triple[];
  nodeCountDelta: number;
  edgeCountDelta: number;
}

export function diffSnapshots(prev: OntologySnapshot, curr: OntologySnapshot): OntologyDiff {
  const prevNodeIds = new Set(prev.nodes.map(n => n.id));
  const currNodeIds = new Set(curr.nodes.map(n => n.id));
  const prevEdgeIds = new Set(prev.triples.map(t => t.id));
  const currEdgeIds = new Set(curr.triples.map(t => t.id));

  return {
    addedNodes: curr.nodes.filter(n => !prevNodeIds.has(n.id)),
    removedNodes: prev.nodes.filter(n => !currNodeIds.has(n.id)),
    addedEdges: curr.triples.filter(t => !prevEdgeIds.has(t.id)),
    removedEdges: prev.triples.filter(t => !currEdgeIds.has(t.id)),
    nodeCountDelta: curr.nodes.length - prev.nodes.length,
    edgeCountDelta: curr.triples.length - prev.triples.length,
  };
}

// ═══ Historical Query ═══

export function getNodeHistory(store: GraphStore, nodeId: string, graph: string): Array<{ timestamp: string; props: Record<string, unknown> }> {
  const snapList = snapshots.get(graph) || [];
  return snapList.map(snap => {
    const node = snap.nodes.find(n => n.id === nodeId);
    return { timestamp: snap.timestamp, props: node?.props || {} };
  });
}

// ═══ Rollback ═══

export function rollbackToSnapshot(store: GraphStore, snapshotId: string, graph: string): boolean {
  const snapList = snapshots.get(graph) || [];
  const snap = snapList.find(s => s.id === snapshotId);
  if (!snap) return false;

  // Safety: create a pre-rollback snapshot
  createSnapshot(store, graph);

  // Delete current edges+ nodes (soft delete — marks valid_to)
  const currentTriples = store.queryTriples({}, graph);
  for (const t of currentTriples) store.deleteEdge(`edge_${t.id}`, graph);
  const allNodes = store.queryNodes(SOGNodeType.PERSON, undefined, graph)
    .concat(store.queryNodes(SOGNodeType.TEAM, undefined, graph))
    .concat(store.queryNodes(SOGNodeType.AGENT, undefined, graph))
    .concat(store.queryNodes(SOGNodeType.TOOL, undefined, graph))
    .concat(store.queryNodes(SOGNodeType.CLIENT, undefined, graph))
    .concat(store.queryNodes(SOGNodeType.EVENT, undefined, graph))
    .concat(store.queryNodes(SOGNodeType.DOCUMENT, undefined, graph))
    .concat(store.queryNodes(SOGNodeType.FINANCIAL, undefined, graph));
  for (const n of allNodes) store.deleteNode(n.id, graph);

  // Restore snapshot nodes
  for (const n of snap.nodes) {
    store.createNode(n.type, n.props, graph);
  }
  // Restore snapshot edges
  for (const t of snap.triples) {
    store.createEdge(t.predicate as any, t.subject_id, t.object_id, t.weight, JSON.parse(t.props_json), graph);
  }

  log.info({ snapshotId, nodeCount: snap.nodeCount, edgeCount: snap.edgeCount }, '[versioning] Rollback complete');
  return true;
}

export function clearVersioning(): void { snapshots.clear(); }
